function getDailyActionTips(state) {
  var urgent = []; // 紧急（最前）
  var tips = [];   // 普通建议
  var p = state.player;
  var needs = state.needs || {};
  var loc = state.trade && state.trade.currentLocation;
  var day = p.day;
  var dayOfWeek = day % 7;
  var mental = p.mental || 0;
  var cash = (state.resources && state.resources.cash) || 0;
  var bankBalance = (state.resources && state.resources.bankBalance) || 0;

  // ===== 紧急警示（无心智门槛，任何时候都显示）=====

  // NPC生日置顶
  if (typeof NPCS !== "undefined") {
    var dayOfYear = ((day - 1) % 365) + 1;
    for (var i = 0; i < NPCS.length; i++) {
      var npc = NPCS[i];
      if (npc.birthday === dayOfYear) {
        var rel = state.relationships && state.relationships[npc.id];
        if (rel && rel.met) {
          urgent.push("🎂 今天是" + npc.name + "的生日！送礼好感×2，快去找ta！");
          break;
        }
      }
    }
  }
  // 里程碑
  if (day === 29) urgent.push("🌟 明天就是第30天！准备迎接一个重要的人生节点。");
  if (day === 59) urgent.push("🌟 明天就是第60天里程碑，回顾一下自己的成长。");
  if (day === 89) urgent.push("🌟 明天就是第90天！这是城市生涯的重要转折点。");

  // 需求警示（基础层，无门槛）
  if (needs.hunger <= 15) urgent.push("🍚 饥饱极低！再不吃东西会晕倒，先找食物！");
  else if (needs.hunger <= 30) tips.push("🍚 饥饱不足，记得先吃顿饭再干活。");
  if (needs.fatigue >= 90) urgent.push("😴 体力耗尽！今天必须休息，否则健康会受损。");
  else if (needs.fatigue >= 75) tips.push("😴 太疲惫了，今天多休息，明天效率更高。");
  if (needs.hygiene <= 10) urgent.push("🚿 卫生告急！形象太差会影响工作收入，快去洗澡。");
  else if (needs.hygiene <= 25) tips.push("🚿 卫生偏低，找个地方洗洗澡保持状态。");

  // 健康警示
  var health = (state.status && state.status.health) || 100;
  if (health <= 30) urgent.push("🏥 健康危险！立刻去诊所看病，否则可能倒下！");
  else if (health <= 50) tips.push("🏥 健康偏低，今天注意休息，考虑去诊所检查。");
  if (state.status && state.status.sick) tips.push("🤒 你生病了，户外工作效率下降，药和休息是最好的选择。");

  // 财务警示
  var villageDebt = (state.resources && (state.resources.villageDebt || state.resources.debt)) || 0;
  var bankDebt = (state.resources && state.resources.bankDebt) || 0;
  if (cash < 30 && day > 3) urgent.push("💸 现金见底！今天必须打工，否则连饭都吃不上。");
  else if (cash < 100 && day > 5) tips.push("💸 现金快用完了，今天务必赚点钱补充。");
  if (villageDebt > 0 && day % 10 === 0) tips.push("🏘️ 村长贷款日息0.35%，欠款越久越多，有钱就去还一点。");

  // ===== 基础层建议（mental≥0，所有人可见）=====

  // 天气
  if (state.weather) {
    var wid = state.weather.weatherId || state.weather.type;
    if (wid === "rainy" || wid === "storm" || wid === "thunderstorm") {
      tips.push("🌧️ 今天下雨，室内工作（工厂/理发/摆摊室内）比户外更合适。");
    } else if (wid === "sunny" || wid === "clear") {
      if (typeof getVendingFootfallMod === "function") {
        var mod = getVendingFootfallMod(state);
        if (mod > 1.2) tips.push("☀️ 天气晴好，客流量高，今天摆摊收益不错！");
      }
    } else if (wid === "heatwave" || wid === "hot") {
      tips.push("🥵 高温天气，多备点水，户外劳动注意防暑。");
    } else if (wid === "coldwave" || wid === "blizzard") {
      tips.push("🧊 寒潮来袭，厚衣物和泡面很畅销，可以考虑囤货出售。");
    }
  }

  // 周期
  if (dayOfWeek === 0 || dayOfWeek === 6) {
    tips.push("🛍️ 今天是周末！公园/商业区客流翻倍，去摆摊能多赚一笔。");
  }
  if (dayOfWeek === 1) {
    tips.push("📋 周一新起点！去工地/工业区打听零工机会，有时会有意外收获。");
  }

  // 属性警示/解锁
  var physique = p.physique || 0;
  var intelligence = p.intelligence || 0;
  var agility = p.agility || 0;
  if (physique < 15) tips.push("💪 体质过低（" + physique + "），负重上限不足15kg，今天先养生休息补体力。");
  if (physique >= 50 && !(state.flags && state.flags._tipPhysique50)) tips.push("💪 体质达到50！可以挑战重体力工作，收入更高。");
  if (intelligence >= 40 && !(state.flags && state.flags._tipInt40)) tips.push("📚 智力达到40！编程技能现在可以更高效地学习。");
  if (agility >= 40 && loc === "market") tips.push("⚡ 敏捷够高，在批发市场讨价还价更有优势！");

  // 技能快升级提示
  if (state.skills) {
    var skillLabels = { sales: "销售", cooking: "烹饪", repair: "修理", fitness: "体能", coding: "编程" };
    for (var sk in state.skills) {
      var s2 = state.skills[sk];
      if (s2 && s2.xp !== undefined && s2.maxXp !== undefined) {
        var pct = s2.maxXp > 0 ? s2.xp / s2.maxXp : 0;
        if (pct >= 0.85 && pct < 1) {
          var label = skillLabels[sk] || sk;
          tips.push("⬆️ " + label + "技能快升级了（" + Math.round(pct*100) + "%），再努力一下！");
          break; // 每次最多提一个技能
        }
      }
    }
  }

  // 工地特殊机会
  if (loc === "school" && intelligence >= 25) {
    tips.push("📚 在大学城，可以接编程外包单，收入不错。");
  }
  if (loc === "construction" && state.flags && state.flags.bossLiReferred) {
    tips.push("🏗️ 李工头已推荐你，可以申请正规工程队，工资大幅提升！");
  }

  // 学历备考提示
  var eduProgress = p.eduProgress;
  if (eduProgress && p.education === 0 && eduProgress.examsPassed < 6) {
    var pctEdu = Math.round((eduProgress.examsPassed / 6) * 100);
    if (eduProgress.studyPoints > 0 || eduProgress.examsPassed > 0) {
      tips.push("🎓 自考本科备考进度：" + pctEdu + "%（" + eduProgress.examsPassed + "/6门已通过），去大学城继续备考！");
    } else if (day > 20) {
      tips.push("🎓 提升学历能解锁更好的工作！去大学城可以参加自考本科备考。");
    }
  }

  // ===== 中级建议（mental≥30）=====
  if (mental >= 30) {
    // 银行存款建议（提高到1万门槛）
    if (cash > 10000 && bankBalance === 0) {
      tips.push("🏦 现金超过1万，去银行存一些，每天收利息，钱生钱更稳健！");
    } else if (cash > 50000) {
      tips.push("🏦 现金充裕，除了银行存款，也可以考虑低风险的贵金属投资分散风险。");
    }

    // 市场事件+位置联动
    if (state.trade && state.trade.marketEvents && state.trade.marketEvents.length > 0) {
      var ev = state.trade.marketEvents[0];
      if (ev.remaining > 0) {
        if (loc === ev.locKey || !ev.locKey) {
          tips.push("📊 市场活动：" + ev.name + " 还剩" + ev.remaining + "天，" +
            (ev.priceMod > 1 ? "价格偏高，适合出货！" : "价格偏低，适合进货！"));
        }
      }
    }

    // 库存提示：背包快满
    if (typeof calcEncumbrance === "function") {
      var enc = calcEncumbrance(state);
      if (enc.ratio > 0.85) {
        tips.push("🎒 背包快满了（" + Math.round(enc.ratio*100) + "%），今天优先出货减轻负重。");
      }
    }
  }

  // ===== 进阶建议（mental≥60，投资/新闻联动）=====
  if (mental >= 60) {
    // 新闻联动投资建议
    var activeNews = state.activeNews || [];
    for (var ni = 0; ni < activeNews.length; ni++) {
      var hl = activeNews[ni].headline || "";
      if (/房地产|楼市|房价/.test(hl)) {
        tips.push("🏠 新闻：" + hl.replace(/[📰🏗️🏘️]/g,"").trim().slice(0,20) + "…→房产投资有压力，工地收入也可能受影响，谨慎操作。");
        break;
      } else if (/科技|电子|数码/.test(hl)) {
        tips.push("💻 新闻：" + hl.replace(/[📱💻🖥️]/g,"").trim().slice(0,20) + "…→科技板块利好，电子股和科技园工作值得关注。");
        break;
      } else if (/通胀|物价|涨价/.test(hl)) {
        tips.push("📈 物价上涨信号——现金贬值，考虑将闲钱存银行或买入贵金属保值。");
