// === 学历系统（大学城）===
if (locKey === "school") {
  const edu = state.player.education || 0;
  const ep = state.player.eduProgress || { studyPoints: 0, examsPassed: 0, totalExams: 6 };
  if (edu < 1) {
    // 备考行动
    const studyReady = ep.examsPassed < ep.totalExams;
    if (studyReady) {
      actions.push({
        id: "edu_study",
        name: "📖 自考备考",
        desc: `消耗20AP，+5学习点（当前${ep.studyPoints}点，本门需150点）。有10%概率智力+1。`,
        ap: 20,
        handler: () => {
          if (!state.player.eduProgress) state.player.eduProgress = { studyPoints: 0, examsPassed: 0, totalExams: 6 };
          state.player.eduProgress.studyPoints = (state.player.eduProgress.studyPoints || 0) + 5;
          consumeAP(20);
          if (Math.random() < 0.10) {
            state.player.attributes.intelligence = Math.min(100, (state.player.attributes.intelligence || 0) + 1);
            StateManager.addMessage("📚 备考中顿悟！智力+1。", "success");
          } else {
            StateManager.addMessage(`📖 备考中…学习点+5（${state.player.eduProgress.studyPoints}/150）`, "info");
          }
        },
      });
    }
    // 参加考试
    const canExam = (ep.studyPoints || 0) >= 150 && ep.examsPassed < ep.totalExams;
    const examPassRate = Math.min(85, 40 + (state.player.attributes.mental || 0) * 0.4 + (state.player.attributes.intelligence || 0) * 0.1);
    actions.push({
      id: "edu_exam",
      name: "📝 参加考试",
      desc: `消耗30AP，需学习点≥150（当前${ep.studyPoints}）。通过率${examPassRate.toFixed(0)}%（第${ep.examsPassed + 1}/6门）。`,
      ap: 30,
      reqFail: !canExam ? (ep.studyPoints < 150 ? `学习点不足（${ep.studyPoints}/150）` : "全部考试已通过") : null,
      handler: () => {
        if (!state.player.eduProgress) state.player.eduProgress = { studyPoints: 0, examsPassed: 0, totalExams: 6 };
        consumeAP(30);
        const rate = Math.min(85, 40 + (state.player.attributes.mental || 0) * 0.4 + (state.player.attributes.intelligence || 0) * 0.1);
        if (Math.random() * 100 < rate) {
          state.player.eduProgress.examsPassed = (state.player.eduProgress.examsPassed || 0) + 1;
          state.player.eduProgress.studyPoints = 0;
          StateManager.addMessage(`🎉 第${state.player.eduProgress.examsPassed}门科目通过！还差${6 - state.player.eduProgress.examsPassed}门。`, "success");
        } else {
          StateManager.addMessage("😞 考试未通过，继续备考再战！", "danger");
        }
      },
    });
    // 申请学历认证
    if (ep.examsPassed >= ep.totalExams) {
      actions.push({
        id: "edu_cert",
        name: "🎓 申请本科学历认证",
        desc: "6门科目全部通过！提交认证，获得本科学历，解锁更多工作机会。",
        ap: 0,
        handler: () => {
          state.player.education = 1;
          StateManager.addMessage("🎓 恭喜！你已取得本科学历，人生新起点！", "success");
          renderAll();
        },
      });
    }
  } else if (edu === 1) {
    actions.push({
      id: "edu_done",
      name: "🎓 本科学历持有者",
      desc: "你已是本科学历，享受更多工作和技能解锁。研究生课程敬请期待。",
      disabled: true,
    });
  }
}

// 2. 旅行
const reachable = getReachableLocations(locKey);

