    renderStreetStats(state);
  } else {
    renderCorporateStats(state);
  }

  renderNeedsBars(state);
  renderDebtInfo(state);
  renderDreamSection(state);
  renderEduSection(state);
  renderLocation(state);
}

function renderEduSection(state) {
  var el = document.getElementById("edu-section");
  if (!el) return;
  var p = state.player;
  var edu = p.education || 0;
  var ep = p.eduProgress || { studyPoints: 0, examsPassed: 0, totalExams: 6 };
  var eduNames = ["大专", "本科", "研究生"];
  var eduIcons = ["🎓", "📜", "🏛️"];
  var hasProgress = edu > 0 || ep.studyPoints > 0 || ep.examsPassed > 0;
  if (!hasProgress) { el.style.display = "none"; return; }
  el.style.display = "block";
  var label = eduIcons[edu] + " " + eduNames[edu] || "大专";
  var progressHtml = "";
  if (edu === 0) {
    var pct = Math.round((ep.examsPassed / (ep.totalExams || 6)) * 100);
    progressHtml =
      '<div style="background:var(--bg-input);border-radius:3px;height:5px;overflow:hidden;margin:4px 0;">' +
      '<div style="width:' + pct + '%;height:100%;background:var(--accent);border-radius:3px;"></div></div>' +
      '<div style="font-size:10px;color:var(--text-muted);">' +
      '备考进度：' + ep.examsPassed + '/' + (ep.totalExams || 6) + '门（学习点' + ep.studyPoints + '/150）</div>';
  }
  el.innerHTML =
    '<h3>🎓 学历</h3>' +
    '<div style="font-size:12px;font-weight:600;">' + label + '</div>' +
    progressHtml;
}

