/**
 * 随机新闻事件 — 影响价格、工作收入、玩家状态
 */

const NEWS_EVENTS = [
  // === 价格影响事件 ===
  {
    id: "metal_boom",
    headline: "📈 国际金属价格暴涨！废品回收利润翻倍！",
    effects: {
      priceMod: { scrap_metal: 2.0, scrap_plastic: 1.5 },
      duration: 5,
    },
    type: "price",
  },
  {
    id: "heatwave",
    headline: "☀️ 高温来袭！瓶装水和饮料需求暴增",
