     - `wallet_returned_good_karma` (day>=22, _returnedWallet): 失主介绍工作 (2 choices, sets _walletKarmaGood)
     - `labor_network_grows` (helpedCoworker + foughtWageTheft, day>=55): 打工人主心骨 (2 choices, sets _laborNetworkGrown, _laborOrganizer)

   **`src/js/phase1/skill_bonuses.js`** — Added after `getFootfallStars()` function
   - New `getNpcPresenceBonus(locKey, jobId, state)` function: iterates NPCS, checks location match, affinity threshold, job match, multiplies all matching bonuses
   - New `getNpcPresenceBonusDesc(locKey, jobId, state)` function: returns text like "👤 老周在场: +20%"
   ```js
   function getNpcPresenceBonus(locKey, jobId, state) {
     if (typeof NPCS === "undefined" || !state.relationships) return 1.0;
     var totalMult = 1.0;
     for (var i = 0; i < NPCS.length; i++) {
       var npc = NPCS[i];
       if (npc.location !== locKey) continue;
       if (!npc.presenceBonus) continue;
       var rel = state.relationships[npc.id];
       var affinity = rel ? (rel.affinity || 0) : 0;
       for (var b = 0; b < npc.presenceBonus.length; b++) {
         var bonus = npc.presenceBonus[b];
         if (affinity < (bonus.minAffinity || 0)) continue;
         var jobMatch = !bonus.jobs || bonus.jobs.indexOf(jobId) >= 0;
         if (!jobMatch) continue;
         totalMult *= (bonus.multiplier || 1.0);
       }
     }
     return totalMult;
   }
   ```

