    el.style.cssText = "margin-top:6px;padding:6px 10px;background:rgba(74,158,92,0.10);border:1px solid rgba(74,158,92,0.30);border-radius:8px;";
    var eduEl = document.getElementById("edu-section");
    if (eduEl && eduEl.parentNode) {
      eduEl.parentNode.insertBefore(el, eduEl.nextSibling);
    } else {
      return;
    }
  }
  el.style.display = "block";
  var earning = mods.earningsBonus > 1.0 ? "收入+" + Math.round((mods.earningsBonus - 1) * 100) + "%" : "";
  var luck = mods.luckBonus > 0 ? " 幸运+" + mods.luckBonus : "";
  el.innerHTML =
    "<h3>🏅 声誉</h3>" +
    '<div style="font-size:12px;font-weight:600;color:var(--accent);">' + mods.reputationLabel + "</div>" +
    (earning || luck
      ? '<div style="font-size:11px;color:var(--text-muted);margin-top:3px;">' + earning + luck + "</div>"
      : "");
}

