  },
];

/** 每日检查动态提示，触发后标记防重复 */
function checkDynamicHints(state) {
  for (var i = 0; i < DYNAMIC_HINTS.length; i++) {
    var hint = DYNAMIC_HINTS[i];
    try {
      if (hint.trigger(state)) {
        state.flags["_hint_" + hint.id] = true;
        StateManager.addMessage(hint.message, "hint");
      }
    } catch (e) {
      /* 防止单条hint出错影响全局 */
    }
  }
}

