function renderMarketSentiment(state, inv) {
  var activeNews = state.activeNews || [];
  var pending = (state.flags && state.flags._pendingFollowUpNews) || [];

  // 计算牛熊分数
  var bullScore = 0, bearScore = 0;
  for (var i = 0; i < activeNews.length; i++) {
    var effs = (activeNews[i].effects || {}).investmentEffect || [];
    for (var j = 0; j < effs.length; j++) {
      var mul = effs[j].mul || 1;
      if (mul > 1) bullScore += (mul - 1) * 8;
      else if (mul < 1) bearScore += (1 - mul) * 8;
    }
  }
  var fg = (inv && inv.btcFearGreed) || 50;
  if (fg > 65) bullScore += (fg - 65) * 0.4;
  else if (fg < 35) bearScore += (35 - fg) * 0.4;

  var sentiment, sentColor;
  if (bullScore > bearScore + 1.5) { sentiment = "🐂 牛市氛围"; sentColor = "var(--success)"; }
  else if (bearScore > bullScore + 1.5) { sentiment = "🐻 熊市氛围"; sentColor = "var(--danger)"; }
  else { sentiment = "⚖️ 震荡市"; sentColor = "var(--accent)"; }

  if (activeNews.length === 0 && pending.length === 0) return "";

  var html = '<div style="margin-bottom:8px;padding:8px 10px;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.06);border-radius:6px;">';
  html += '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:5px;">';
  html += '<span style="font-size:11px;font-weight:bold;color:' + sentColor + ';">' + sentiment + '</span>';
  html += '<span style="font-size:10px;color:var(--text-muted);">BTC恐贪: ' + fg + '/100</span>';
  html += '</div>';

  // 当前活跃新闻（最多3条）
  var shownNews = 0;
  for (var k = 0; k < activeNews.length && shownNews < 3; k++) {
    var news = activeNews[k];
    var daysLeft = ((news._appliedDay || 0) + ((news.effects && news.effects.duration) || 5)) - state.player.day;
    if (daysLeft <= 0) continue;
    html += '<div style="font-size:10px;color:var(--text-light);padding:1px 0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">';
    html += news.headline + ' <span style="color:var(--text-muted);">(' + daysLeft + '天)</span>';
    html += '</div>';
    shownNews++;
  }

  // 即将触发的级联新闻预告
  if (pending.length > 0) {
    html += '<div style="font-size:10px;color:var(--accent);margin-top:4px;margin-bottom:2px;">⏰ 近期动向：</div>';
    var fuRef = typeof NEWS_FOLLOWUP !== "undefined" ? NEWS_FOLLOWUP : {};
    var shownPend = 0;
    for (var m = 0; m < pending.length && shownPend < 2; m++) {
      var pitem = pending[m];
      var fu = fuRef[pitem.id];
      if (!fu) continue;
      var daysUntil = pitem.triggerDay - state.player.day;
      html += '<div style="font-size:10px;color:var(--text-muted);padding:1px 0;">';
      html += (daysUntil <= 0 ? "今日" : daysUntil + "天后") + "：" + fu.headline;
      html += '</div>';
      shownPend++;
    }
  }

  html += '</div>';
  return html;
}

