  if (job.startupCost) {
    state.resources.cash -= job.startupCost;
  }

  // 计算收入（含新闻+情绪修正）
  let pay = job.payCalc(state);
  if (state._jobMultipliers && state._jobMultipliers[job.id]) {
    pay = Math.floor(pay * state._jobMultipliers[job.id]);
