}
// 新人保护：前15天废品回收+5，苦力类+3
if (state.player.day <= 15) {
  const boostedJobs = [
    "waste_recycling",
    "manual_labor_construction",
    "warehouse_worker",
    "factory_work_assembly",
  ];
  if (boostedJobs.includes(job.id)) {
    const newbieBonus = job.id === "waste_recycling" ? 2 : 2;
    pay += newbieBonus;
  }
}
