323	/** 获取当前梦想定义 */
324	function getCurrentDream(state) {
325	  var id = state.flags && state.flags._dreamId;
326	  if (!id) return null;
327	  return (
328	    DREAMS.find(function (d) {
329	      return d.id === id;
330	    }) || null
331	  );
332	}
333	
334	/** 每日检查梦想里程碑进度 */
335	function checkDreamProgress(state) {
336	  var dream = getCurrentDream(state);
337	  if (!dream) return;
338	
339	  var currentMilestone = state.flags._dreamMilestone || 0;
340	  if (currentMilestone >= dream.milestones.length) return; // 已全部完成
341	
342	  var milestone = dream.milestones[currentMilestone];
343	  if (!milestone) return;
344	
345	  // 检查条件
346	  if (milestone.condition(state)) {
347	    state.flags._dreamMilestone = currentMilestone + 1;
348	    // 防重复触发
349	    var flagKey = "_dreamMilestoneShown_" + milestone.id;
350	    if (!state.flags[flagKey]) {
351	      state.flags[flagKey] = true;
352	      StateManager.addMessage(
353	        dream.icon +
354	          " 【梦想里程碑：" +
355	          milestone.title +
356	          "】\n" +
357	          milestone.story,
358	        "event",
359	      );
360	    }
361	  }
362	}
363	
364	/** 获取梦想进度百分比 */
365	function getDreamProgress(state) {
366	  var dream = getCurrentDream(state);
367	  if (!dream) return 0;
368	  var done = state.flags._dreamMilestone || 0;
369	  return Math.min(100, Math.round((done / dream.milestones.length) * 100));
370	}
371	
372	/** 获取当前里程碑标题（用于UI显示） */
373	function getDreamCurrentTitle(state) {
374	  var dream = getCurrentDream(state);
375	  if (!dream) return "";
376	  var idx = state.flags._dreamMilestone || 0;
377	  if (idx >= dream.milestones.length) return "圆梦！ 🎉";
378	  return dream.milestones[idx].title;
379	}
